const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const needles = ee.Geometry.Point([-114.6133, 34.8453]);
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]);
  const date = '2017-06-21';
  const endDate = '2017-06-22'; // End date is exclusive, so it covers June 21st.

  // 2. Data Acquisition
  const collection = ee.ImageCollection('MODIS/051/MYD11A1')
    .filterDate(date, endDate)
    .select(['LST_Day_1km', 'QC_Day']);

  // Function to mask invalid LST pixels based on QC_Day band
  const maskLST = function(image) {
    const qc = image.select('QC_Day');
    // Bits 0-1: Mandatory cloud mask
    // 00 (0): LST produced, good quality, not used for cloud screen
    // 01 (1): LST produced, good quality, passed cloud screen
    // 10 (2): LST produced, unreliable or less than optimal quality
    // 11 (3): LST not produced due to cloud
    const qualityBits = qc.bitwiseAnd(3);
    const goodQuality = qualityBits.lte(1); // Keep 00 and 01

    // Bits 2-3: Data quality flag
    // 00 (0): Good data quality
    // 01 (1): Other quality
    // 10 (2): Other quality
    // 11 (3): Bad data quality
    const dataQualityBits = qc.rightShift(2).bitwiseAnd(3);
    const goodDataQuality = dataQualityBits.eq(0); // Keep 00

    // Combine masks
    const combinedMask = goodQuality.and(goodDataQuality);

    return image.updateMask(combinedMask).copyProperties(image, ['system:time_start']);
  };

  const processLocation = async function(locationName, geometry) {
    let filteredCol = collection.filterBounds(geometry);

    if (filteredCol.size().getInfo() === 0) {
      console.log(`No images found for ${locationName} on ${date}.`);
      return { lst: null, pixelCount: 0, cloudPercent: 100 };
    }

    const image = filteredCol.first();
    const maskedImage = maskLST(image);

    // Scaling factor for LST_Day_1km is 0.02
    const scaleFactor = ee.Number(0.02);

    // Reduce region to get LST and pixel count
    const stats = await maskedImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000, // MODIS 1km resolution
      maxPixels: 1e9
    }).getInfo();

    const lstValue = stats['LST_Day_1km'];
    const pixelCount = stats['LST_Day_1km_count'];

    // If no valid pixels remain after masking
    if (!pixelCount || pixelCount === 0) {
      console.log(`Images found for ${locationName}, but 0 valid pixels after cloud mask.`);
      return { lst: null, pixelCount: 0, cloudPercent: 100 };
    }

    // Calculate LST in Celsius
    const lstCelsius = (lstValue * scaleFactor.getInfo()) - 273.15;

    // Estimate cloud percentage
    const totalPixels = image.select('LST_Day_1km').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    const cloudPercent = totalPixels > 0 ? ((totalPixels - pixelCount) / totalPixels) * 100 : 100;

    return { lst: lstCelsius, pixelCount: pixelCount, cloudPercent: cloudPercent };
  };

  console.log(`Analyzing LST on ${date}...`);
  const needlesData = await processLocation('Needles', needles);
  const phoenixData = await processLocation('Phoenix', phoenix);

  // 5. Validation & Final Answer
  if (needlesData.lst === null || phoenixData.lst === null) {
    if (needlesData.pixelCount === 0 || phoenixData.pixelCount === 0) {
      if (collection.filterBounds(needles).size().getInfo() === 0 || collection.filterBounds(phoenix).size().getInfo() === 0) {
        console.log("C1: Empty Collection (No images found for one or both locations).");
        console.log("C1");
      } else {
        console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain for one or both locations).");
        console.log("C2");
      }
    } else {
      console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
      console.log("C3");
    }
    return;
  }

  console.log(`Needles LST: ${needlesData.lst.toFixed(2)} °C, Pixels: ${needlesData.pixelCount}, Cloud: ${needlesData.cloudPercent.toFixed(1)}%`);
  console.log(`Phoenix LST: ${phoenixData.lst.toFixed(2)} °C, Pixels: ${phoenixData.pixelCount}, Cloud: ${phoenixData.cloudPercent.toFixed(1)}%`);

  if (needlesData.lst > phoenixData.lst) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
